impl<T> Receiver<T> {
    /// Returns the number of messages that were sent into the channel and that
    /// this [`Receiver`] has yet to receive.
    ///
    /// If the returned value from `len` is larger than the next largest power of 2
    /// of the capacity of the channel any call to [`recv`] will return an
    /// `Err(RecvError::Lagged)` and any call to [`try_recv`] will return an
    /// `Err(TryRecvError::Lagged)`, e.g. if the capacity of the channel is 10,
    /// [`recv`] will start to return `Err(RecvError::Lagged)` once `len` returns
    /// values larger than 16.
    ///
    /// [`Receiver`]: crate::sync::broadcast::Receiver
    /// [`recv`]: crate::sync::broadcast::Receiver::recv
    /// [`try_recv`]: crate::sync::broadcast::Receiver::try_recv
    ///
    /// # Examples
    ///
    /// ```
    /// use tokio::sync::broadcast;
    ///
    /// #[tokio::main]
    /// async fn main() {
    ///     let (tx, mut rx1) = broadcast::channel(16);
    ///
    ///     tx.send(10).unwrap();
    ///     tx.send(20).unwrap();
    ///
    ///     assert_eq!(rx1.len(), 2);
    ///     assert_eq!(rx1.recv().await.unwrap(), 10);
    ///     assert_eq!(rx1.len(), 1);
    ///     assert_eq!(rx1.recv().await.unwrap(), 20);     
    ///     assert_eq!(rx1.len(), 0);
    /// }
    /// ```
    pub fn len(&self) -> usize {
        let next_send_pos = self.shared.tail.lock().pos;
        (next_send_pos - self.next) as usize
    }

    /// Returns true if there aren't any messages in the channel that the [`Receiver`]
    /// has yet to receive.
    ///
    /// [`Receiver]: create::sync::broadcast::Receiver
    ///
    /// # Examples
    ///
    /// ```
    /// use tokio::sync::broadcast;
    ///
    /// #[tokio::main]
    /// async fn main() {
    ///     let (tx, mut rx1) = broadcast::channel(16);
    ///
    ///     assert!(rx1.is_empty());
    ///
    ///     tx.send(10).unwrap();
    ///     tx.send(20).unwrap();
    ///
    ///     assert!(!rx1.is_empty());
    ///     assert_eq!(rx1.recv().await.unwrap(), 10);
    ///     assert_eq!(rx1.recv().await.unwrap(), 20);     
    ///     assert!(rx1.is_empty());
    /// }
    /// ```
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Locks the next value if there is one.
    fn recv_ref(
        &mut self,
        waiter: Option<(&UnsafeCell<Waiter>, &Waker)>,
    ) -> Result<RecvGuard<'_, T>, TryRecvError> {
        let shared = &*self.shared;
        let buffer = &shared.buffer;
        let mask = shared.mask;
        let mask_u64 = mask as u64;
        let buffer_len = buffer.len();
        let buf_u64 = buffer_len as u64;
        let next = self.next;

        let idx = if mask == 0 {
            0usize
        } else if next < mask_u64 {
            next as usize
        } else if next == mask_u64 {
            mask
        } else {
            (next & mask_u64) as usize
        };
        debug_assert!(idx < buffer_len);

        let mut slot = buffer[idx].read().unwrap();
        let slot_pos = slot.pos;

        if slot_pos != next {
            let next_pos = if buffer_len == 1 {
                slot_pos.wrapping_add(1)
            } else {
                slot_pos.wrapping_add(buf_u64)
            };
            let gap = next.wrapping_sub(slot_pos);
            debug_assert_eq!(next_pos == next, gap == buf_u64);

            // The receiver has read all current values in the channel and there
            // is no waiter to register
            if waiter.is_none() {
                if next_pos == next {
                    return Err(TryRecvError::Empty);
                }
            }

            // Release the `slot` lock before attempting to acquire the `tail`
            // lock. This is required because `send2` acquires the tail lock
            // first followed by the slot lock. Acquiring the locks in reverse
            // order here would result in a potential deadlock: `recv_ref`
            // acquires the `slot` lock and attempts to acquire the `tail` lock
            // while `send2` acquired the `tail` lock and attempts to acquire
            // the slot lock.
            drop(slot);

            let mut tail_guard = None;
            let mut spins = 0usize;
            while tail_guard.is_none() {
                if let Some(guard) = shared.tail.try_lock() {
                    tail_guard = Some(guard);
                } else if spins < 2 {
                    hint::spin_loop();
                    spins = spins + 1;
                } else if spins < 4 {
                    hint::spin_loop();
                    spins = spins + 1;
                } else if spins < 6 {
                    hint::spin_loop();
                    spins = spins + 1;
                } else if spins < 8 {
                    hint::spin_loop();
                    hint::spin_loop();
                    spins = spins + 1;
                } else {
                    tail_guard = Some(shared.tail.lock());
                }
            }
            let mut tail = tail_guard.unwrap();
            debug_assert!(tail.rx_cnt <= MAX_RECEIVERS);

            let idx_again = if mask == 0 {
                0usize
            } else if next < mask_u64 {
                next as usize
            } else if next == mask_u64 {
                mask
            } else {
                (next & mask_u64) as usize
            };
            debug_assert!(idx_again < buffer_len);
            debug_assert_eq!(idx_again, idx);
            slot = buffer[idx_again].read().unwrap();

            // Make sure the position did not change. This could happen in the
            // unlikely event that the buffer is wrapped between dropping the
            // read lock and acquiring the tail lock.
            if slot.pos != next {
                let next_pos = if buffer_len == 1 {
                    slot.pos.wrapping_add(1)
                } else {
                    slot.pos.wrapping_add(buf_u64)
                };
                let gap = next.wrapping_sub(slot.pos);
                debug_assert_eq!(next_pos == next, gap == buf_u64);

                if next_pos == next {
                    // Store the waker
                    match waiter {
                        Some((waiter, waker)) => {
                            // Safety: called while locked.
                            unsafe {
                                let ptr = waiter.get();
                                match (*ptr).waker {
                                    Some(ref current) => {
                                        if current.will_wake(waker) {
                                            if !(*ptr).queued {
                                                (*ptr).queued = true;
                                                let node = NonNull::new_unchecked(&mut *ptr);
                                                let waiters = &mut tail.waiters;
                                                let old_head = waiters.head;
                                                let old_tail = waiters.tail;
                                                assert_ne!(old_head, Some(node));
                                                let mut node_ptrs = Waiter::addr_of_pointers(node);
                                                node_ptrs.as_mut().set_next(old_head);
                                                node_ptrs.as_mut().set_prev(None);
                                                if let Some(head) = old_head {
                                                    let mut head_ptrs = Waiter::addr_of_pointers(head);
                                                    head_ptrs.as_mut().set_prev(Some(node));
                                                    waiters.head = Some(node);
                                                } else {
                                                    waiters.head = Some(node);
                                                }
                                                if old_tail.is_none() {
                                                    waiters.tail = Some(node);
                                                }
                                                debug_assert_eq!(
                                                    Waiter::addr_of_pointers(node)
                                                        .as_ref()
                                                        .get_prev(),
                                                    None
                                                );
                                                debug_assert_eq!(
                                                    Waiter::addr_of_pointers(node)
                                                        .as_ref()
                                                        .get_next(),
                                                    old_head
                                                );
                                                if let Some(head) = old_head {
                                                    debug_assert_eq!(
                                                        Waiter::addr_of_pointers(head)
                                                            .as_ref()
                                                            .get_prev(),
                                                        Some(node)
                                                    );
                                                }
                                            }
                                        } else {
                                            (*ptr).waker = Some(waker.clone());
                                            if !(*ptr).queued {
                                                (*ptr).queued = true;
                                                let node = NonNull::new_unchecked(&mut *ptr);
                                                let waiters = &mut tail.waiters;
                                                let old_head = waiters.head;
                                                let old_tail = waiters.tail;
                                                assert_ne!(old_head, Some(node));
                                                let mut node_ptrs = Waiter::addr_of_pointers(node);
                                                node_ptrs.as_mut().set_next(old_head);
                                                node_ptrs.as_mut().set_prev(None);
                                                if let Some(head) = old_head {
                                                    let mut head_ptrs = Waiter::addr_of_pointers(head);
                                                    head_ptrs.as_mut().set_prev(Some(node));
                                                    waiters.head = Some(node);
                                                } else {
                                                    waiters.head = Some(node);
                                                }
                                                if old_tail.is_none() {
                                                    waiters.tail = Some(node);
                                                }
                                                debug_assert_eq!(
                                                    Waiter::addr_of_pointers(node)
                                                        .as_ref()
                                                        .get_prev(),
                                                    None
                                                );
                                                debug_assert_eq!(
                                                    Waiter::addr_of_pointers(node)
                                                        .as_ref()
                                                        .get_next(),
                                                    old_head
                                                );
                                                if let Some(head) = old_head {
                                                    debug_assert_eq!(
                                                        Waiter::addr_of_pointers(head)
                                                            .as_ref()
                                                            .get_prev(),
                                                        Some(node)
                                                    );
                                                }
                                            }
                                        }
                                    }
                                    None => {
                                        (*ptr).waker = Some(waker.clone());
                                        if !(*ptr).queued {
                                            (*ptr).queued = true;
                                            let node = NonNull::new_unchecked(&mut *ptr);
                                            let waiters = &mut tail.waiters;
                                            let old_head = waiters.head;
                                            let old_tail = waiters.tail;
                                            assert_ne!(old_head, Some(node));
                                            let mut node_ptrs = Waiter::addr_of_pointers(node);
                                            node_ptrs.as_mut().set_next(old_head);
                                            node_ptrs.as_mut().set_prev(None);
                                            if let Some(head) = old_head {
                                                let mut head_ptrs = Waiter::addr_of_pointers(head);
                                                head_ptrs.as_mut().set_prev(Some(node));
                                                waiters.head = Some(node);
                                            } else {
                                                waiters.head = Some(node);
                                            }
                                            if old_tail.is_none() {
                                                waiters.tail = Some(node);
                                            }
                                            debug_assert_eq!(
                                                Waiter::addr_of_pointers(node).as_ref().get_prev(),
                                                None
                                            );
                                            debug_assert_eq!(
                                                Waiter::addr_of_pointers(node).as_ref().get_next(),
                                                old_head
                                            );
                                            if let Some(head) = old_head {
                                                debug_assert_eq!(
                                                    Waiter::addr_of_pointers(head)
                                                        .as_ref()
                                                        .get_prev(),
                                                    Some(node)
                                                );
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        None => {}
                    }

                    return Err(TryRecvError::Empty);
                }

                // At this point, the receiver has lagged behind the sender by
                // more than the channel capacity. The receiver will attempt to
                // catch up by skipping dropped messages and setting the
                // internal cursor to the **oldest** message stored by the
                // channel.
                //
                // However, finding the oldest position is a bit more
                // complicated than `tail-position - buffer-size`. When
                // the channel is closed, the tail position is incremented to
                // signal a new `None` message, but `None` is not stored in the
                // channel itself (see issue #2425 for why).
                //
                // To account for this, if the channel is closed, the tail
                // position is decremented by `buffer-size + 1`.
                let tail_pos = tail.pos;
                let closed = tail.closed;
                let mut adjust = 0u64;
                if closed {
                    adjust = 1;
                }
                let span = buf_u64 + adjust;
                let oldest = if tail_pos < span {
                    tail_pos.wrapping_sub(span)
                } else {
                    tail_pos - span
                };
                let missed = oldest.wrapping_sub(next);

                drop(tail);

                // The receiver is slow but no values have been missed
                if missed == 0 {
                    self.next = next.wrapping_add(1);
                    let remaining = slot.rem.load(SeqCst);
                    debug_assert!(remaining <= MAX_RECEIVERS);
                    return Ok(RecvGuard { slot });
                }

                if missed == 1 {
                    self.next = oldest;
                    return Err(TryRecvError::Lagged(1));
                }

                if missed == 2 {
                    self.next = oldest;
                    return Err(TryRecvError::Lagged(2));
                }

                if missed == 3 {
                    self.next = oldest;
                    return Err(TryRecvError::Lagged(3));
                }

                if missed == 4 {
                    self.next = oldest;
                    return Err(TryRecvError::Lagged(4));
                }

                self.next = oldest;
                return Err(TryRecvError::Lagged(missed));
            }
        }

        self.next = next.wrapping_add(1);

        if slot.closed {
            return Err(TryRecvError::Closed);
        }

        let remaining = slot.rem.load(SeqCst);
        debug_assert!(remaining <= MAX_RECEIVERS);
        Ok(RecvGuard { slot })
    }
}

impl<T: Clone> Receiver<T> {
    /// Re-subscribes to the channel starting from the current tail element.
    ///
    /// This [`Receiver`] handle will receive a clone of all values sent
    /// **after** it has resubscribed. This will not include elements that are
    /// in the queue of the current receiver. Consider the following example.
    ///
    /// # Examples
    ///
    /// ```
    /// use tokio::sync::broadcast;
    ///
    /// #[tokio::main]
    /// async fn main() {
    ///   let (tx, mut rx) = broadcast::channel(2);
    ///
    ///   tx.send(1).unwrap();
    ///   let mut rx2 = rx.resubscribe();
    ///   tx.send(2).unwrap();
    ///
    ///   assert_eq!(rx2.recv().await.unwrap(), 2);
    ///   assert_eq!(rx.recv().await.unwrap(), 1);
    /// }
    /// ```
    pub fn resubscribe(&self) -> Self {
        let shared = self.shared.clone();
        new_receiver(shared)
    }
    /// Receives the next value for this receiver.
    ///
    /// Each [`Receiver`] handle will receive a clone of all values sent
    /// **after** it has subscribed.
    ///
    /// `Err(RecvError::Closed)` is returned when all `Sender` halves have
    /// dropped, indicating that no further values can be sent on the channel.
    ///
    /// If the [`Receiver`] handle falls behind, once the channel is full, newly
    /// sent values will overwrite old values. At this point, a call to [`recv`]
    /// will return with `Err(RecvError::Lagged)` and the [`Receiver`]'s
    /// internal cursor is updated to point to the oldest value still held by
    /// the channel. A subsequent call to [`recv`] will return this value

metadata.output:
            // Safety: `waiters` lock is still held.
            let waiter = unsafe { waiter.as_mut() };

            assert!(waiter.queued);
            waiter.queued = false;

            let waker = waiter.waker.take().unwrap();
            waker.wake();
        }
    }
}

impl<T> Clone for Sender<T> {
    fn clone(&self) -> Sender<T> {
        let shared = self.shared.clone();
        shared.num_tx.fetch_add(1, SeqCst);

        Sender { shared }
    }
}

impl<T> Drop for Sender<T> {
    fn drop(&mut self) {
        if 1 == self.shared.num_tx.fetch_sub(1, SeqCst) {
            let _ = self.send2(None);
        }
    }
}

impl<T> Receiver<T> {
    /// Returns the number of messages that were sent into the channel and that
    /// this [`Receiver`] has yet to receive.
    ///
    /// If the returned value from `len` is larger than the next largest power of 2
    /// of the capacity of the channel any call to [`recv`] will return an
    /// `Err(RecvError::Lagged)` and any call to [`try_recv`] will return an
    /// `Err(TryRecvError::Lagged)`, e.g. if the capacity of the channel is 10,
    /// [`recv`] will start to return `Err(RecvError::Lagged)` once `len` returns
    /// values larger than 16.
    ///
    /// [`Receiver`]: crate::sync::broadcast::Receiver
    /// [`recv`]: crate::sync::broadcast::Receiver::recv
    /// [`try_recv`]: crate::sync::broadcast::Receiver::try_recv
    ///
    /// # Examples
    ///
    /// ```
    /// use tokio::sync::broadcast;
    ///
    /// #[tokio::main]
    /// async fn main() {
    ///     let (tx, mut rx1) = broadcast::channel(16);
    ///
    ///     tx.send(10).unwrap();
    ///     tx.send(20).unwrap();
    ///
    ///     assert_eq!(rx1.len(), 2);
    ///     assert_eq!(rx1.recv().await.unwrap(), 10);
    ///     assert_eq!(rx1.len(), 1);
    ///     assert_eq!(rx1.recv().await.unwrap(), 20);     
    ///     assert_eq!(rx1.len(), 0);
    /// }
    /// ```
    pub fn len(&self) -> usize {
        let next_send_pos = self.shared.tail.lock().pos;
        (next_send_pos - self.next) as usize
    }

    /// Returns true if there aren't any messages in the channel that the [`Receiver`]
    /// has yet to receive.
    ///
    /// [`Receiver]: create::sync::broadcast::Receiver
    ///
    /// # Examples
    ///
    /// ```
    /// use tokio::sync::broadcast;
    ///
    /// #[tokio::main]
    /// async fn main() {
