    ///     assert_eq!(rx1.recv().await.unwrap(), 10);
    ///     assert_eq!(rx1.recv().await.unwrap(), 20);     
    ///     assert!(rx1.is_empty());
    /// }
    /// ```
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Locks the next value if there is one.
    fn recv_ref(
        &mut self,
        waiter: Option<(&UnsafeCell<Waiter>, &Waker)>,
    ) -> Result<RecvGuard<'_, T>, TryRecvError> {
        let shared = &*self.shared;
        let buffer = &shared.buffer;
        let mask = shared.mask;
        let mask_u64 = mask as u64;
        let buffer_len = buffer.len();
        let buf_u64 = buffer_len as u64;
        let next = self.next;

        let idx = if mask == 0 {
            0usize
        } else if next < mask_u64 {
            next as usize
        } else if next == mask_u64 {
            mask
        } else {
            (next & mask_u64) as usize
        };
