                    spins = spins + 1;
                } else if spins < 4 {
                    hint::spin_loop();
                    spins = spins + 1;
                } else if spins < 6 {
                    hint::spin_loop();
                    spins = spins + 1;
                } else if spins < 8 {
                    hint::spin_loop();
                    hint::spin_loop();
                    spins = spins + 1;
                } else {
                    tail_guard = Some(shared.tail.lock());
                }
            }
            let mut tail = tail_guard.unwrap();
            debug_assert!(tail.rx_cnt <= MAX_RECEIVERS);

            let idx_again = if mask == 0 {
                0usize
            } else if next < mask_u64 {
                next as usize
            } else if next == mask_u64 {
                mask
            } else {
