                                        if !(*ptr).queued {
                                            (*ptr).queued = true;
                                            let node = NonNull::new_unchecked(&mut *ptr);
                                            let waiters = &mut tail.waiters;
                                            let old_head = waiters.head;
                                            let old_tail = waiters.tail;
                                            assert_ne!(old_head, Some(node));
                                            let mut node_ptrs = Waiter::addr_of_pointers(node);
                                            node_ptrs.as_mut().set_next(old_head);
                                            node_ptrs.as_mut().set_prev(None);
                                            if let Some(head) = old_head {
                                                let mut head_ptrs = Waiter::addr_of_pointers(head);
                                                head_ptrs.as_mut().set_prev(Some(node));
                                                waiters.head = Some(node);
                                            } else {
                                                waiters.head = Some(node);
                                            }
                                            if old_tail.is_none() {
                                                waiters.tail = Some(node);
                                            }
                                            debug_assert_eq!(
                                                Waiter::addr_of_pointers(node).as_ref().get_prev(),
                                                None
                                            );
                                            debug_assert_eq!(
                                                Waiter::addr_of_pointers(node).as_ref().get_next(),
                                                old_head
                                            );
                                            if let Some(head) = old_head {
                                                debug_assert_eq!(
                                                    Waiter::addr_of_pointers(head)
                                                        .as_ref()
                                                        .get_prev(),
                                                    Some(node)
