use tokio::sync::broadcast::error::RecvError;

#[tokio::main]
async fn main() {
    let (tx, rx) = tokio::sync::broadcast::channel::<u32>(4);
    drop(tx);

    let mut rx_clone = rx.resubscribe();
    drop(rx);

    assert!(matches!(rx_clone.recv().await, Err(RecvError::Closed)));
    assert!(matches!(rx_clone.recv().await, Err(RecvError::Closed)));

    let (tx, rx) = tokio::sync::broadcast::channel::<u32>(4);
    let mut rx2 = rx.resubscribe();
    tx.send(1).unwrap();
    drop(tx);
    assert_eq!(rx2.recv().await.unwrap(), 1);
    assert!(matches!(rx2.recv().await, Err(RecvError::Closed)));
    assert!(matches!(rx2.recv().await, Err(RecvError::Closed)));

    println!("ok");
}
